#!/usr/bin/env node
/**
 * Writes src/lib/llm-parameter-catalog.data.ts — the Manager's mirror of the
 * backend's LLM parameter catalog, src/main/resources/llm/model-parameters.json.
 *
 *   npm run gen:llm-params            regenerate
 *   npm run gen:llm-params -- --check exit 1 if the mirror is out of date
 *
 * The output is the JSON verbatim, so `llm-parameter-catalog.test.ts` can
 * compare the two with a deep equality and fail on any drift. Never edit the
 * generated file by hand; change the backend JSON and rerun this.
 */
import { readFileSync, writeFileSync } from "node:fs";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const here = dirname(fileURLToPath(import.meta.url));
const source = resolve(here, "../../../src/main/resources/llm/model-parameters.json");
const target = resolve(here, "../src/lib/llm-parameter-catalog.data.ts");

const catalog = JSON.parse(readFileSync(source, "utf-8"));

const output = `// GENERATED by scripts/gen-llm-parameter-catalog.mjs from
// src/main/resources/llm/model-parameters.json — do not edit by hand.
// Regenerate with \`npm run gen:llm-params\`; llm-parameter-catalog.test.ts fails on drift.
import type { RawParameterCatalog } from "@/lib/llm-parameter-catalog";

export const LLM_PARAMETER_CATALOG_DATA: RawParameterCatalog = ${JSON.stringify(catalog, null, 2)};
`;

if (process.argv.includes("--check")) {
  let current = "";
  try {
    current = readFileSync(target, "utf-8");
  } catch {
    // missing counts as stale
  }
  if (current.replace(/\r\n/g, "\n") !== output) {
    console.error("llm-parameter-catalog.data.ts is out of date: run `npm run gen:llm-params`.");
    process.exit(1);
  }
  console.log("llm-parameter-catalog.data.ts is up to date.");
} else {
  writeFileSync(target, output);
  console.log(`Wrote ${target}`);
}
